  function convert(s) {
    for (const [from,to] of phrases) s = s.split(from).join(to);
    return Array.from(s, ch => chars[ch] || ch).join('');
  }
  function clone(v) {
    if (typeof v === 'string') return convert(v);
    if (Array.isArray(v)) return v.map(clone);
    if (v && typeof v === 'object') {
      const out = {};
      for (const [k,val] of Object.entries(v)) out[k] = clone(val);
      return out;
    }
    return v;
  }

  I18N['zh-TW'] = clone(I18N['zh-CN']);
